if (prescale_reg > 0) begin
  s_axis_tready <= 1'b0;
  prescale_reg <= prescale_reg - 19'd1;
end else if (bit_cnt == 0) begin
  s_axis_tready <= 1'b1;
  busy <= 1'b0;
  if (s_axis_tvalid) begin
    s_axis_tready <= !s_axis_tready;
    prescale_reg <= {prescale, 3'b000} - 19'd1;
    bit_cnt <= 4'(DATA_WIDTH + 1);
    data_reg <= {1'b1, s_axis_tdata};
    txd <= 1'b0;
    busy <= 1'b1;
  end
end else begin
  if (bit_cnt > 1) begin
    bit_cnt <= bit_cnt - 4'd1;
    prescale_reg <= {prescale, 3'b000} - 19'd1;
    {data_reg, txd} <= {1'b0, data_reg};
  end else if (bit_cnt == 1) begin
    bit_cnt <= bit_cnt - 4'd1;
    prescale_reg <= {prescale, 3'b000};
    txd <= 1'b1;
  end
end
